// Wallapop - enriquecer desde la API de detalle.
//
// Antes esto lo intentaba el enriquecedor universal de color pidiendo el HTML
// de la ficha, y acertaba el 0,7% de las veces: 2.883 intentos y 2.862 se
// quedaron sin color. No estaba bloqueado -devolvia 200 y 210 KB-, es que
// es.wallapop.com es una SPA de Next.js y el dato no vive en el markup, vive
// dentro de __NEXT_DATA__. La API de detalle lo da ya masticado y en espanol.

const out = $input.item.json;
const id = $('Loop: coche por coche').item.json.id;

// El nodo HTTP va con fullResponse + neverError a proposito: asi un 404 llega
// como dato y no como excepcion, que es justo lo que interesa (404 = retirado).
const status = Number(out.statusCode || 0);
let body = out.body !== undefined ? out.body : out.data;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
body = body || {};

function esc(v) { if (v === null || v === undefined || v === '') return null; return "'" + String(v).replace(/'/g, "''") + "'"; }

// El anuncio ya no existe. Se da de baja aqui mismo en lugar de esperar al
// verificador: la peticion ya esta hecha y la respuesta no admite dudas.
if (status === 404 || status === 410) {
  return [{ json: { sql: 'UPDATE moveadvisor_market_offers SET is_active=FALSE, last_checked_at=NOW(), enrich_tried_at=NOW(), updated_at=NOW() WHERE id=' + esc(id), count: 1 } }];
}

// Un 429, un 5xx o un timeout son pasajeros: no se toca el coche. El intento se
// fecha 29 dias atras a proposito, no en NOW(): asi la cola avanza hoy -no se
// atasca en el mismo coche- pero manana vuelve a intentarlo, en vez de
// desterrarlo un mes entero por un tropiezo de una tarde.
if (status !== 200) {
  return [{ json: { sql: "UPDATE moveadvisor_market_offers SET enrich_tried_at = NOW() - INTERVAL '29 days' WHERE id=" + esc(id), count: 1 } }];
}

const ta = body.type_attributes || {};
const val = function (k) { return ta[k] && ta[k].value != null ? String(ta[k].value) : ''; };

const doors = parseInt(val('doors'), 10);
const seats = parseInt(val('seats'), 10);
const cv = Math.round(parseFloat(val('horse_power')));

// El resto de la base dice 'Manual' y 'Automatica' (395.528 y 390.279 filas).
// El semiautomatico -DSG, S-tronic y compania- entra como automatica: para
// quien busca coche es lo mismo, y partirlo en tres crearia un tercer valor
// que ningun filtro mira.
const gearMap = { manual: 'Manual', automatic: 'Automatica', semiautomatic: 'Automatica' };
const transmission = gearMap[val('gear_box')] || '';

// Se mapea desde 'value' y no desde 'text' porque el texto viene en el idioma
// de la peticion y el value es estable. Lo que no este en la tabla se guarda
// con el texto traducido, que es mejor que tirarlo.
const bodyMap = {
  small_car: 'Pequeño', family_car: 'Familiar', four_x_four: 'SUV',
  mini_van: 'Monovolumen', sedan: 'Berlina', coupe: 'Coupé',
  cabrio: 'Descapotable o convertible', van: 'Furgoneta', pick_up: 'Furgoneta'
};
let bodyType = bodyMap[val('body_type')] || (ta.body_type && ta.body_type.text ? String(ta.body_type.text) : '');
if (bodyType === 'SUV/4X4') bodyType = 'SUV';

const ecoMap = { zero: '0 Emisiones', eco: 'ECO', c: 'C', b: 'B' };
const eco = ecoMap[val('eco_label')] || '';

// El color no lo da la API, ni en busqueda ni en detalle. Algunos vendedores lo
// escriben en la descripcion ('Pintura: Pintura metalizada Gris Delfin'), asi
// que se busca ahi y solo se acepta si sale un color reconocible. Medido sobre
// 77 coches reales: 16 mencionan pintura o color y de esos se sacan 7, un 9%.
// Poco, pero la descripcion ya viene en la respuesta y no cuesta una peticion
// mas. El resto se queda sin color, que es lo que hay: Wallapop no lo pide.
let color = '';
{
  const d = String(body.description || '');
  const m = d.match(/(?:pintura|color)\s*:?\s*([^\n\r.;]{0,60})/i);
  if (m) {
    const known = ['blanco', 'negro', 'gris', 'plata', 'plateado', 'azul', 'rojo', 'verde', 'amarillo', 'naranja', 'marron', 'beige', 'dorado', 'granate', 'burdeos', 'violeta', 'morado'];
    const hit = known.find(function (k) { return m[1].toLowerCase().indexOf(k) !== -1; });
    if (hit) color = hit.charAt(0).toUpperCase() + hit.slice(1);
  }
}

const sets = [];
if (!isNaN(doors) && doors > 0) sets.push('doors=' + doors);
if (!isNaN(seats) && seats > 0) sets.push('seats=' + seats);
// Los CV ya vienen del scraper en el 98% de los casos: aqui solo se rellenan huecos.
if (!isNaN(cv) && cv > 0) sets.push('power_cv=COALESCE(power_cv,' + cv + ')');
if (transmission) sets.push('transmission=' + esc(transmission));
if (bodyType) sets.push('body_type=' + esc(bodyType));
if (eco) sets.push('environmental_label=' + esc(eco));
// Un color ya puesto no se pisa: puede haberlo escrito una persona.
if (color) sets.push("color=COALESCE(NULLIF(color,'')," + esc(color) + ")");
// modified_date viene en segundos, no en milisegundos.
if (body.modified_date && Number(body.modified_date) > 0) sets.push('source_updated_at=to_timestamp(' + Math.round(Number(body.modified_date)) + ')');

// Ha respondido 200, luego el anuncio sigue vivo. Se aprovecha el viaje para
// refrescarlo y de paso corregir un falso inactivo si lo hubiera.
sets.push('is_active=TRUE', 'last_checked_at=NOW()', 'enrich_tried_at=NOW()', 'updated_at=NOW()');

const sql = 'UPDATE moveadvisor_market_offers SET ' + sets.join(', ') + ' WHERE id=' + esc(id);
return [{ json: { sql: sql, count: 1 } }];
